// Package sqleval corresponds to Python structured/core/sql_res_evaluation/__init__.py.
// Prompt text is generated by tools/oracle/gen_prompts.py — do not edit prompts.go by hand.
package sqleval

import (
	"context"
	"errors"

	"void2md/structured/pkg/chatmodel"
	"void2md/structured/pkg/jsonmin"
	"void2md/structured/pkg/pyrepr"
	"void2md/structured/pkg/sqlutil"
)

// Result corresponds to Python arun's (answer, input_tokens, output_tokens, error)
// quadruple; Error is a pointer for Python's None.
type Result struct {
	Answer       string
	InputTokens  int
	OutputTokens int
	Error        *string
}

// Run corresponds to sql_res_evaluation.arun.
func Run(
	ctx context.Context,
	query string,
	llm chatmodel.ChatModel,
	dbInfo string,
	sql string,
	resRows [][]any,
	evidence *string,
) (Result, error) {
	ev := ""
	if evidence != nil {
		ev = *evidence
	}

	// Python embeds res_rows via str.format, equivalent to str(list_of_tuples).
	data := map[string]string{
		"db_info":       dbInfo,
		"query":         query,
		"generated_sql": sql,
		"sql_result":    pyrepr.Rows(resRows),
		"evidence":      ev,
	}
	humanMsg, err := sqlutil.PyFormat(prompt, data)
	if err != nil {
		return Result{}, err
	}

	resp, chatErr := llm.AInvoke(ctx, humanMsg)
	if chatErr != nil {
		// Python: raise ValueError(f"LLM call failed: {err.msg}") (Chinese in the original source)
		return Result{}, errors.New("LLM call failed: " + chatErr.Msg)
	}

	var answer string
	// nil Error means Python's error is falsy (None or ""); the agent only truthiness-checks it.
	var errMsg *string

	result := jsonmin.Text2JSON(resp.Content)
	if v, ok := result["final_answer"]; ok {
		answer = sqlutil.PyTruthyString(v, true)
	} else {
		// Python: error = result.get("explanation", "")
		s := sqlutil.PyTruthyString(result["explanation"], true)
		if s != "" {
			errMsg = &s
		}
	}

	return Result{
		Answer:       answer,
		InputTokens:  resp.InputTokens,
		OutputTokens: resp.OutputTokens,
		Error:        errMsg,
	}, nil
}
